{"command":"python3 << 'PYEOF'
import csv

# Read stops
with open('workspace/gtfs_extract/stops.txt', 'r') as f:
    reader = csv.DictReader(f)
    stops = list(reader)

print(f"Total stops: {len(stops)}")

# Check for invalid coordinates (lat: -90 to 90, lon: -180 to 180)
invalid_coords = []
for s in stops:
    try:
        lat = float(s['stop_lat'])
        lon = float(s['stop_lon'])
        if lat < -90 or lat > 90 or lon < -180 or lon > 180:
            invalid_coords.append(s)
    except (ValueError, KeyError):
        invalid_coords.append(s)

print(f"Invalid coordinates: {len(invalid_coords)}")
for s in invalid_coords:
    print(f"  {s['stop_id']}: lat={s['stop_lat']}, lon={s['stop_lon']}")

# Check for duplicate stop_ids
seen = set()
duplicates = []
for s in stops:
    sid = s['stop_id']
    if sid in seen:
        duplicates.append(s)
    else:
        seen.add(sid)

print(f"Duplicate stops: {len(duplicates)}")
for s in duplicates:
    print(f"  {s['stop_id']}: {s['stop_name']}")

# Check for missing stop names
missing_names = []
for s in stops:
    name = s.get('stop_name', '').strip()
    if name == '':
        missing_names.append(s)

print(f"Missing stop names: {len(missing_names)}")
for s in missing_names:
    print(f"  {s['stop_id']}: name='{s.get('stop_name', '')}'")

PYEOF"}
